        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return (obj[0], obj[1])
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(points, origin):
        best = None
        best_d = None
        for p in points or []:
            pp = pos(p)
            if pp is None:
